//! Plans against an independent implementation in NumPy, with the historical model, which draws
//! nothing at random. The fixture is generated by `scripts/reference/planning.py`.

#![allow(clippy::unwrap_used)]

use finalytics::planning::{Month, Outcome, PlanOptions, PlanResults};
use finalytics::{Assets, datasets};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/planning.json")).unwrap()
}

#[track_caller]
fn close(actual: f64, expected: &Value, what: &str) {
    let expected = expected.as_f64().unwrap();
    assert!(
        (actual - expected).abs() <= 1e-9 * expected.abs().max(1.0),
        "{what}: {actual} against the reference {expected}"
    );
}

#[track_caller]
fn optional(actual: Option<f64>, expected: &Value, what: &str) {
    match actual {
        None => assert!(expected.is_null(), "{what}: none against {expected}"),
        Some(a) => close(a, expected, what),
    }
}

#[track_caller]
fn month(actual: Option<Month>, expected: &Value, what: &str) {
    assert_eq!(
        actual.map(|m| m.to_string()),
        expected.as_str().map(str::to_owned),
        "{what}"
    );
}

fn outcome(actual: &Outcome, expected: &Value, what: &str) {
    optional(
        actual.chance,
        &expected["chance"],
        &format!("{what} chance"),
    );
    close(
        actual.typical,
        &expected["typical"],
        &format!("{what} typical"),
    );
    month(
        actual.runs_out,
        &expected["runs_out"],
        &format!("{what} runs out"),
    );
}

fn check(name: &str, r: &PlanResults, e: &Value) {
    assert_eq!(
        r.simulations as u64,
        e["simulations"].as_u64().unwrap(),
        "{name}"
    );
    optional(r.outcome.chance, &e["chance"], &format!("{name}: chance"));
    for (q, v) in [
        ("p10", r.end_value.p10),
        ("p25", r.end_value.p25),
        ("p50", r.end_value.p50),
        ("p75", r.end_value.p75),
        ("p90", r.end_value.p90),
    ] {
        close(v, &e["end"][q], &format!("{name}: end {q}"));
    }
    let medians = e["median_by_month"].as_array().unwrap();
    assert_eq!(r.values.len(), medians.len(), "{name}: months recorded");
    for (t, (v, m)) in r.values.iter().zip(medians).enumerate() {
        close(v.p50, m, &format!("{name}: median in month {t}"));
    }
    for (k, (f, p)) in r
        .flows
        .iter()
        .zip(e["paid_in_full"].as_array().unwrap())
        .enumerate()
    {
        optional(f.paid_in_full, p, &format!("{name}: flow {k} paid in full"));
    }
    if let Some(expected) = e["chance_by_month"].as_array() {
        assert_eq!(r.chance_by_month.len(), expected.len());
        for (t, (c, x)) in r.chance_by_month.iter().zip(expected).enumerate() {
            close(*c, x, &format!("{name}: chance by month {t}"));
        }
        optional(r.shortfall, &e["shortfall"], &format!("{name}: shortfall"));
    }
    if let Some(p) = &r.payments {
        let x = &e["payments"];
        close(p.paid, &x["paid"], &format!("{name}: paid"));
        optional(
            p.paid_when_short,
            &x["paid_when_short"],
            &format!("{name}: paid when short"),
        );
        month(
            p.runs_short,
            &x["runs_short"],
            &format!("{name}: runs short"),
        );
        month(
            p.runs_out_weak,
            &x["runs_out_weak"],
            &format!("{name}: weak"),
        );
        month(
            p.runs_out_average,
            &x["runs_out_average"],
            &format!("{name}: average"),
        );
        month(
            p.runs_out_strong,
            &x["runs_out_strong"],
            &format!("{name}: strong"),
        );
        month(
            p.lasts_until,
            &x["lasts_until"],
            &format!("{name}: lasts until"),
        );
    }
    let c = r.changes.as_ref().unwrap();
    let x = &e["changes"];
    assert_eq!(c.to_reach, x["to_reach"].as_bool().unwrap(), "{name}");
    optional(
        c.saving.as_ref().map(|a| a.to),
        &x["saving"],
        &format!("{name}: saving"),
    );
    optional(
        c.start_value.as_ref().map(|a| a.to),
        &x["start_value"],
        &format!("{name}: start value"),
    );
    optional(
        c.amount.as_ref().map(|a| a.to),
        &x["amount"],
        &format!("{name}: amount"),
    );
    month(
        c.date.as_ref().map(|d| d.to),
        &x["date"],
        &format!("{name}: date"),
    );
    outcome(
        &r.what_if.lower_returns,
        &e["lower_returns"],
        &format!("{name}: lower returns"),
    );
    outcome(
        r.what_if.crash.as_ref().unwrap(),
        &e["crash"],
        &format!("{name}: crash"),
    );
    let w = r.what_if.crash_window.unwrap();
    let x = &e["crash_window"];
    month(Some(w.from), &x["from"], &format!("{name}: crash from"));
    month(Some(w.to), &x["to"], &format!("{name}: crash to"));
    month(
        Some(w.placed),
        &x["placed"],
        &format!("{name}: crash placed"),
    );
    close(w.loss, &x["loss"], &format!("{name}: crash loss"));
    let x = &e["risk"];
    close(
        r.risk.typical_return,
        &x["typical_return"],
        &format!("{name}: typical return"),
    );
    close(
        r.risk.worst_year.unwrap(),
        &x["worst_year"],
        &format!("{name}: worst year"),
    );
    close(
        r.risk.largest_fall,
        &x["largest_fall"],
        &format!("{name}: largest fall"),
    );
    close(
        r.risk.volatility,
        &x["volatility"],
        &format!("{name}: volatility"),
    );
}

#[test]
fn plans_match_the_reference() {
    let assets = Assets::builder()
        .prices(datasets::asset_class_prices())
        .build()
        .unwrap();
    let fixture = fixture();
    let cases = fixture["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 4);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let options: PlanOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let plan = assets.plan_with(&options).unwrap();
        check(name, &plan.results, &case["expected"]);
    }
}
